mapper.select:
SELECT p.photo_id AS photoId, p.image_url AS imageUrl, p.created_at AS createdAt, IF(pl.photo_id IS NULL, FALSE, TRUE) AS liked, p.editable AS editable, ( SELECT GROUP_CONCAT(SUBSTRING_INDEX(u.user_email, '@', 1)) FROM photo_tag pt JOIN user u ON pt.user_id=u.user_id WHERE pt.photo_id=p.photo_id )AS partners FROM photo p LEFT JOIN photo_like pl ON p.photo.id=pl.photo_id AND pl.user_id=#{userId} WHERE p.user_id=#{userId}
AND DATE(p.created_at) >= #{cond.startDate}
AND DATE(p.created_at) <= #{cond.endDate}
AND pl.photo_id IS NOT NULL
AND pl.photo_id IS NULL
-- 이메일 앞부분(아이디)이 특정 값에 포함된 사용자가 태그된 사진만 조회
AND EXISTS( SELECT 1 FROM photo_tag pt JOIN user u ON pt.user_id = u.user_id WHERE pt.photo_id=p.photo_id AND SUBSTRING_INDEX(u.user_email, '@', 1) IN
#{email}
)
-- 커서 기반 페이지네이션-무한 스크롤을 위한 커서 방식
AND p.photo_id < #{cond.cursor}
-- 최신순 정렬 -- limit 값만큼만 조회-> cond.limit에 따라 프론트에서 요청 개수 조절 가능 ORDER BY p.photo_id DESC LIMIT #{cond.limit}
